func TestCheckInIntervalIsTheCLIDefaultUnlessSet(t *testing.T) {
	t.Cleanup(func() { SetCheckInSeconds(0) })

	if got := checkInInterval(); got != aliveAnnounce {
		t.Errorf("default check-in interval = %v, want %v", got, aliveAnnounce)
	}

	SetCheckInSeconds(15)
	if got := checkInInterval(); got != 15*time.Second {
		t.Errorf("check-in interval after SetCheckInSeconds(15) = %v, want 15s", got)
	}

	for _, reset := range []int{0, -5} {
		SetCheckInSeconds(15)
		SetCheckInSeconds(reset)
		if got := checkInInterval(); got != aliveAnnounce {
			t.Errorf("check-in interval after SetCheckInSeconds(%d) = %v, want the default %v", reset, got, aliveAnnounce)
		}
	}
}

package edgevpn

import (
	"encoding/base64"
	"testing"

	"github.com/mudler/edgevpn/pkg/node"
)

func TestValidateToken(t *testing.T) {
	valid := node.GenerateNewConnectionData().Base64()
	const cut = "This doesn't look like a complete key. It may have been cut off while copying."
	const empty = "Paste a network key first."
	cases := map[string]string{
		valid: "",
		"  " + valid[:40] + "\n" + valid[40:] + "\n": "", // whitespace from a terminal
		"":                    empty,
		valid[:len(valid)-22]: cut, // what adb input truncation produced
		"not a key at all":    cut,
	}
	for in, want := range cases {
		if got := ValidateToken(in); got != want {
			t.Errorf("ValidateToken(%.20q) = %q, want %q", in, got, want)
		}
	}
}

// A key without an mDNS name cannot find devices on the same Wi-Fi, and one
// without a positive message size gives pubsub a limit of zero bytes, so the
// ledger never syncs. edgevpn always writes both into the keys it generates.
func TestValidateTokenRejectsAKeyWithoutMDNSOrMessageSize(t *testing.T) {
	const missing = "This key is missing parts EdgeVPN needs. Copy it again from a device that is already in the network."
	noMDNS := node.GenerateNewConnectionData()
	noMDNS.MDNS = ""
	noSize := node.GenerateNewConnectionData()
	noSize.MaxMessageSize = 0
	negativeSize := node.GenerateNewConnectionData()
	negativeSize.MaxMessageSize = -1
	cases := map[string]*node.YAMLConnectionConfig{
		"no mdns":                   noMDNS,
		"no max_message_size":       noSize,
		"negative max_message_size": negativeSize,
	}
	for name, cfg := range cases {
		if got := ValidateToken(cfg.Base64()); got != missing {
			t.Errorf("%s: ValidateToken = %q, want %q", name, got, missing)
		}
	}
}

func TestValidateTokenRejectsYAMLWithoutKeys(t *testing.T) {
	tok := base64.StdEncoding.EncodeToString([]byte("room: x\n"))
	if got := ValidateToken(tok); got != "This key is missing parts EdgeVPN needs. Copy it again from a device that is already in the network." {
		t.Fatalf("got %q", got)
	}
}

package edgevpn

import (
	"testing"
	"time"

	"github.com/libp2p/go-libp2p/p2p/muxer/yamux"
)

func TestMuxerKeepalive(t *testing.T) {
	defaultInterval := yamux.DefaultTransport.Config().KeepAliveInterval
	defaultWriteTimeout := yamux.DefaultTransport.Config().ConnectionWriteTimeout

	cfg := muxerTransport().Config()
	if !cfg.EnableKeepAlive {
		t.Error("keepalive is disabled")
	}
	if cfg.KeepAliveInterval != 10*time.Second {
		t.Errorf("KeepAliveInterval = %v, want 10s", cfg.KeepAliveInterval)
	}
	if cfg.ConnectionWriteTimeout != 5*time.Second {
		t.Errorf("ConnectionWriteTimeout = %v, want 5s", cfg.ConnectionWriteTimeout)
	}

	d := yamux.DefaultTransport.Config()
	if d.KeepAliveInterval != defaultInterval || d.ConnectionWriteTimeout != defaultWriteTimeout {
		t.Error("yamux.DefaultTransport was modified")
	}
	if muxerTransport() == yamux.DefaultTransport {
		t.Error("muxerTransport returned the shared default")
	}
}

package edgevpn

import (
	"testing"

	dht "github.com/libp2p/go-libp2p-kad-dht"
)

const vmPeer = "/ip4/10.0.2.2/tcp/40001/p2p/12D3KooWD7dVUX9WL1NbxASy1GHkKqT7teqCZq7H6HBHrP6EqsdJ"

func resetExtraPeers(t *testing.T) {
	t.Cleanup(func() {
		if err := SetExtraPeers(""); err != nil {
			t.Errorf("reset extra peers: %v", err)
		}
	})
}

// With no extra peers the bootstrap list stays empty, which makes edgevpn
// use the public DHT bootstrap peers, as the CLI does.
func TestNetworkConfigHasNoBootstrapPeersByDefault(t *testing.T) {
	resetExtraPeers(t)
	cfg := networkConfig("some-token", "10.1.0.2")
	if len(cfg.Discovery.BootstrapPeers) != 0 {
		t.Errorf("BootstrapPeers = %v, want none", cfg.Discovery.BootstrapPeers)
	}
}

// An extra peer is dialled directly at start, next to the public bootstrap
// peers, so the DHT keeps working as it does without one.
func TestExtraPeersAreAddedAfterThePublicBootstrapPeers(t *testing.T) {
	resetExtraPeers(t)
	if err := SetExtraPeers(" " + vmPeer + "\n"); err != nil {
		t.Fatalf("SetExtraPeers: %v", err)
	}

	got := networkConfig("some-token", "10.1.0.2").Discovery.BootstrapPeers

	want := len(dht.DefaultBootstrapPeers) + 1
	if len(got) != want {
		t.Fatalf("got %d bootstrap peers, want %d: %v", len(got), want, got)
	}
	for i, p := range dht.DefaultBootstrapPeers {
		if got[i] != p.String() {
			t.Errorf("bootstrap peer %d = %q, want %q", i, got[i], p.String())
		}
	}
	if got[want-1] != vmPeer {
		t.Errorf("last bootstrap peer = %q, want %q", got[want-1], vmPeer)
	}
}

// edgevpn dereferences the peer ID of every bootstrap address, so one
// without /p2p/<id> would crash the node; it is refused up front instead.
func TestSetExtraPeersRefusesAnAddressWithoutAPeerID(t *testing.T) {
	resetExtraPeers(t)
	for _, bad := range []string{"/ip4/10.0.2.2/tcp/40001", "not an address"} {
		if err := SetExtraPeers(bad); err == nil {
			t.Errorf("SetExtraPeers(%q) succeeded, want an error", bad)
		}
	}
	if got := networkConfig("some-token", "10.1.0.2").Discovery.BootstrapPeers; len(got) != 0 {
		t.Errorf("BootstrapPeers after refused calls = %v, want none", got)
	}
}

